changeSet.sql:

DECLARE @sql NVARCHAR(250);
DECLARE @cur CURSOR;

SET @cur = CURSOR FOR 
select 'ALTER TABLE AssetType DROP CONSTRAINT ' + c.name as script from sys.default_constraints c 
inner join sys.objects t on t.object_id = c.parent_object_id and t.name = 'AssetType' 
inner join sys.columns f on f.column_id = c.parent_column_id and f.name in ('IsDescriptionEnabled', 'IsDescriptionVisibleByDefault')

OPEN @cur
FETCH NEXT FROM @cur INTO @sql

WHILE @@FETCH_STATUS = 0
BEGIN
	EXEC sp_executesql @sql
	FETCH NEXT FROM @cur INTO @sql 
END; 

CLOSE @cur;
DEALLOCATE @cur;
